/**
 * Typed registry clients. Everything under ./clients/ is generated by
 * `bun run tools clients` (tools/lib/capture/codegen.ts): Hey API clients from the
 * GitHub, crates.io, npm, PyPI, NuGet, Maven Central and R-universe OpenAPI descriptions,
 * and the gql.tada introspection
 * of the prefix.dev GraphQL schema. This module only binds them to one transport.
 */
import { print } from "@0no-co/graphql.web";
import { initGraphQLTada, type TadaDocumentNode } from "gql.tada";
import * as crates from "@/tools/lib/capture/clients/crates/client/index.ts";
import * as github from "@/tools/lib/capture/clients/github/client/index.ts";
import * as maven from "@/tools/lib/capture/clients/maven/client/index.ts";
import * as npm from "@/tools/lib/capture/clients/npm/client/index.ts";
import * as nuget from "@/tools/lib/capture/clients/nuget/client/index.ts";
import type { introspection } from "@/tools/lib/capture/clients/prefix/graphql-env.d.ts";
import * as pypi from "@/tools/lib/capture/clients/pypi/client/index.ts";
import * as runiverse from "@/tools/lib/capture/clients/runiverse/client/index.ts";

export const BASE_URLS = {
  github: "https://api.github.com",
  crates: "https://crates.io",
  npm: "https://registry.npmjs.org",
  pypi: "https://pypi.org",
  nuget: "https://api.nuget.org",
  nugetSearch: "https://azuresearch-usnc.nuget.org",
  maven: "https://central.sonatype.com",
  mavenRepo: "https://repo1.maven.org",
  prefix: "https://prefix.dev/api/graphql",
} as const;

/** Every R-universe is its own subdomain. */
export const universeUrl = (universe: string): string => `https://${universe}.r-universe.dev`;

export type Transport = { fetch: typeof fetch; githubToken?: string };

export type Clients = {
  github: github.Client;
  crates: crates.Client;
  npm: npm.Client;
  pypi: pypi.Client;
  nuget: nuget.Client;
  maven: maven.Client;
  /** Unbound: calls pass `baseUrl: universeUrl(name)`. */
  runiverse: runiverse.Client;
  prefix: <Result, Variables>(
    document: TadaDocumentNode<Result, Variables>,
    variables: Variables,
  ) => Promise<Result>;
};

/** GraphQL documents checked against the prefix.dev schema at type-check time. */
export const graphql = initGraphQLTada<{
  introspection: introspection;
  // RFC 3339 timestamps and ISO dates arrive as JSON strings.
  scalars: { DateTime: string; NaiveDate: string };
}>();

export class GraphQLError extends Error {
  constructor(
    readonly endpoint: string,
    readonly errors: unknown[],
  ) {
    super(`GraphQL errors from ${endpoint}: ${JSON.stringify(errors)}`);
    this.name = "GraphQLError";
  }
}

export function createClients({ fetch, githubToken }: Transport): Clients {
  const auth: Record<string, string> = githubToken ? { Authorization: `Bearer ${githubToken}` } : {};
  return {
    github: github.createClient(
      github.createConfig({
        baseUrl: BASE_URLS.github,
        fetch,
        headers: { Accept: "application/vnd.github+json", ...auth },
      }),
    ),
    crates: crates.createClient(crates.createConfig({ baseUrl: BASE_URLS.crates, fetch })),
    npm: npm.createClient(npm.createConfig({ baseUrl: BASE_URLS.npm, fetch })),
    pypi: pypi.createClient(pypi.createConfig({ baseUrl: BASE_URLS.pypi, fetch })),
    nuget: nuget.createClient(nuget.createConfig({ baseUrl: BASE_URLS.nuget, fetch })),
    maven: maven.createClient(maven.createConfig({ baseUrl: BASE_URLS.maven, fetch })),
    runiverse: runiverse.createClient(runiverse.createConfig({ fetch })),
    async prefix(document, variables) {
      const response = await fetch(BASE_URLS.prefix, {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify({ query: print(document), variables }),
      });
      const payload = (await response.json()) as { data?: unknown; errors?: unknown[] };
      if (payload.errors?.length) throw new GraphQLError(BASE_URLS.prefix, payload.errors);
      return payload.data as never;
    },
  };
}
